import{_ as i,C as s,o as r,c as l,a3 as o,E as a,j as n}from"./chunks/framework.BZKbe9n2.js";const _=JSON.parse('{"title":"Quelldienste","description":"","frontmatter":{},"headers":[],"relativePath":"de/administration/sources.md","filePath":"de/administration/sources.md"}'),d={name:"de/administration/sources.md"};function u(c,e,g,m,h,p){const t=s("Screenshot");return r(),l("div",null,[e[0]||(e[0]=o('<h1 id="quelldienste" tabindex="-1">Quelldienste <a class="header-anchor" href="#quelldienste" aria-label="Permalink to &quot;Quelldienste&quot;">​</a></h1><p>Quelldienste sind optionale, eigenständige Container, die Musik aus anderen Quellen anbieten – etwa von Streamingdiensten oder Online-Shops. Sie leben in eigenen Repositories (Organisation <code>anthology-sources</code>) unter eigenen Lizenzen; Anthology spricht mit ihnen über eine dokumentierte Schnittstelle (siehe <a href="/anthology/next/de/source-api/">API für Quellen</a>).</p><h2 id="einen-quelldienst-hinzufugen" tabindex="-1">Einen Quelldienst hinzufügen <a class="header-anchor" href="#einen-quelldienst-hinzufugen" aria-label="Permalink to &quot;Einen Quelldienst hinzufügen&quot;">​</a></h2><ol><li>Nimm den Container des Dienstes in den Pod auf, mit dem Import-Volume unter <code>/data/imports</code>.</li><li>Trage seine URL in <code>ANTHOLOGY_SOURCE_SERVICES</code> ein (durch Kommas getrennt, z. B. <code>http://localhost:8420</code>).</li><li>Starte den Server neu. Er prüft jeden Dienst jede Minute; <strong>Streaming › Quellenstatus</strong> zeigt, ob er verfügbar ist und warum nicht.</li></ol><p>Braucht ein Dienst eine Anmeldung, tragen Administratoren sie unter <strong>Einstellungen › Quellen</strong> ein. Die Werte werden verschlüsselt gespeichert und nie wieder angezeigt.</p><h2 id="quellen-nutzen" tabindex="-1">Quellen nutzen <a class="header-anchor" href="#quellen-nutzen" aria-label="Permalink to &quot;Quellen nutzen&quot;">​</a></h2><p>Redaktion und Administratoren durchsuchen auf der Seite <strong>Streaming</strong> eine Quelle oder fügen einen Link ein. Anthology zeigt bei jedem Titel, ob du ihn schon hast und in welcher Qualität. Eine Bestellung lädt die Titel im Hintergrund und importiert sie; der Import bestätigt sich selbst, und sein Ergebnis wird pro Titel angezeigt.</p>',7)),a(t,{name:"source-search",alt:"Ein bei einem Quelldienst gefundenes Album mit seinen Titeln"}),e[1]||(e[1]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Deine Verantwortung"),n("p",null,"Downloads von kommerziellen Diensten unterliegen deren Bedingungen. Die Nutzung von Quelldiensten liegt bei dir.")],-1))])}const b=i(d,[["render",u]]);export{_ as __pageData,b as default};
